<span class="line"><span style="color:#7F848E;font-style:italic;"> * </span><span style="color:#C678DD;font-style:italic;">@param</span><span style="color:#E06C75;font-style:italic;"> column_names_len</span><span style="color:#7F848E;font-style:italic;"> [in] Number of requested columns.</span></span>
